import runpy
import unittest


def rodar():
    """Roda solucao.py do zero e devolve o que ele definiu."""
    return runpy.run_path("solucao.py")


class TestInverter(unittest.TestCase):
    def test_inverter_na_hora_devolve_a_lista_invertida(self):
        """inverter_na_hora devolve a lista invertida"""
        self.assertEqual(rodar()["inverter_na_hora"]([1, 2, 3]), [3, 2, 1])

    def test_inverter_na_hora_muda_a_lista_original(self):
        """inverter_na_hora muda a lista original no lugar"""
        numeros = [1, 2, 3]
        rodar()["inverter_na_hora"](numeros)
        self.assertEqual(numeros, [3, 2, 1])

    def test_ao_contrario_devolve_invertida_sem_mudar(self):
        """ao_contrario devolve a lista invertida e nao muda a original"""
        numeros = [1, 2, 3]
        self.assertEqual(rodar()["ao_contrario"](numeros), [3, 2, 1])
        self.assertEqual(numeros, [1, 2, 3])

    def test_ao_contrario_com_um_item_so(self):
        """ao_contrario com um item so devolve a lista igual"""
        self.assertEqual(rodar()["ao_contrario"]([7]), [7])

